const clients = 100;
const maxRetries = 3; // 1 initial + 3 retries = up to 4 attempts each
let downstreamCalls = 0;
function dependencyIsDown() { downstreamCalls++; return false; /* always fails */ }
for (let i = 0; i < clients; i++) {
  let attempts = 0;
  let ok = false;
  while (!ok && attempts <= maxRetries) {
    attempts++;
    ok = dependencyIsDown();
  }
}
const amplification = downstreamCalls / clients;
console.log('downstream calls: ' + downstreamCalls + ', amplification: ' + amplification + 'x');
